int main(int argc, char** argv){
    const int n = 2000, m = 2000, q = 100000, V = 100000;
    const char mode = (argc > 1) ? argv[1][0] : 'A';
    srand(20261227);            // 固定种子，保证实验可复现
    printf("%d %d\n", n, m);
    for (int i = 1; i <= n; ++i){
