#include<iostream>
int main(){

    int n;
    std::cin>>n;

    for(int i=1;i<=n;i++){
        for(int j=1;j<=n-i;j++) std::cout <<' ';
        for(int k=1;k<=2*i-1;k++) std::cout <<'*';
        std::cout << '\n';
    }
    for(int j=1;j<=n-1;j++) std::cout <<' ';
    std::cout << '|';

    return 0;
}

#include<iostream>

double get_grade(int score){
    if(score>=90) return 4;
    if(score>=85) return 3.6;
    if(score>=80) return 3.3;
    if(score>=77) return 3.0;
    if(score>=73) return 2.6;
    if(score>=70) return 2.3;
    if(score>=67) return 2.0;
    if(score>=63) return 1.6;
    if(score>=60) return 1.3;
    return 0;
}

int main(){

    int n,score,credit,credits=0;
    double total=0;
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        scanf("%d %d",&credit,&score);
        credits+=credit;
        total+=credit*get_grade(score);

    }
    printf("%.2lf",double(total)/credits);

    return 0;
}

// 我不知道啊，我开始筛了
// 原来被vector坑了，气死我了
#include <iostream>
#include<vector>
int n,tot=0;
int cnt;
int vis[10001]={0};
int prime[10001]={0};
int main(){

    std::cin >> n;
    for(int i=2;i<=n;i++){
        if(!vis[i]){ prime[++tot]=i;}
        // 无敌了，这错了
        for(int j=1;j<=tot && i*prime[j]<=n;j++){    
            vis[i*prime[j]]=1;
            if(i % prime[j] == 0) break;
        }
    }
    for(cnt=2;cnt<=n && !(!vis[cnt] && !vis[n-cnt]);cnt++);
    std::cout << cnt << ' ' << n-cnt;
    return 0;
}

