#pragma once

#include "raylib.h"

#if defined(__cplusplus)
extern "C" {            // Prevents name mangling of functions
#endif
    /// <summary>
    /// Looks for the specified resource dir in several common locations
    /// The working dir
    /// The app dir
    /// Up to 3 levels above the app dir
    /// When found the dir will be set as the working dir so that assets can be loaded relative to that.
    /// </summary>
    /// <param name="folderName">The name of the resources dir to look for</param>
    /// <returns>True if a dir with the name was found, false if no change was made to the working dir</returns>
    inline static bool SearchAndSetResourceDir(const char* folderName)
    {
        // check the working dir
        if (DirectoryExists(folderName))
        {
            ChangeDirectory(TextFormat("%s/%s", GetWorkingDirectory(), folderName));
            return true;
        }

        const char* appDir = GetApplicationDirectory();

        // check the applicationDir
        const char* dir = TextFormat("%s%s", appDir, folderName);
        if (DirectoryExists(dir))
        {
            ChangeDirectory(dir);
            return true;
        }

        // check one up from the app dir
        dir = TextFormat("%s../%s", appDir, folderName);
        if (DirectoryExists(dir))
        {
            ChangeDirectory(dir);
            return true;
        }

        // check two up from the app dir
        dir = TextFormat("%s../../%s", appDir, folderName);
        if (DirectoryExists(dir))
        {
            ChangeDirectory(dir);
            return true;
        }

        // check three up from the app dir
        dir = TextFormat("%s../../../%s", appDir, folderName);
        if (DirectoryExists(dir))
        {
            ChangeDirectory(dir);
            return true;
        }

        return false;
    }

#if defined(__cplusplus)
}
#endif

/*
 * =============================================================================
 * MVC — Controller（控制层）
 * -----------------------------------------------------------------------------
 * 处理输入（鼠标），调用 Model 修改状态，并驱动 View 所需的一帧流程。
 * 不直接绘制；不包含走子规则（规则在 Model）。
 * =============================================================================
 */
#pragma once

#include "raylib.h"
#include "model/ChessModel.h"
#include "view/ChessView.h"

class ChessController {
public:
    ChessController(ChessModel& model, ChessView& view) : model_(model), view_(view) {}

    // 每帧：读取输入并交给 Model
    void update();

private:
    ChessModel& model_;
    ChessView& view_;
};

/*
 * =============================================================================
 * MVC — Model（模型层）
 * -----------------------------------------------------------------------------
 * 只描述“棋局状态”与规则：棋盘、棋子、轮到谁走、是否将军/将杀/和棋、
 * 合法走法生成与执行。不依赖 raylib，不知道屏幕坐标或鼠标。
 * 由 Controller 调用以响应输入；由 View 只读查询用于绘制。
 * =============================================================================
 */
#pragma once

#include <cstdint>
#include <string>
#include <vector>

enum class ChessColor : std::uint8_t { White, Black };

enum class PieceType : std::uint8_t { None, Pawn, Rook, Knight, Bishop, Queen, King };

struct Piece {
    PieceType type = PieceType::None;
    ChessColor color = ChessColor::White;

    bool empty() const { return type == PieceType::None; }
};

struct Square {
    std::int8_t f = -1;  // file 0..7 (a..h)
    std::int8_t r = -1;  // rank 0..7 (白方底线 rank0，黑方底线 rank7)

    bool valid() const { return f >= 0 && f < 8 && r >= 0 && r < 8; }
    int index() const { return static_cast<int>(r) * 8 + static_cast<int>(f); }

    static Square fromFR(int file, int rank) {
        return {static_cast<std::int8_t>(file), static_cast<std::int8_t>(rank)};
    }

    friend bool operator==(Square a, Square b) { return a.f == b.f && a.r == b.r; }
    friend bool operator!=(Square a, Square b) { return !(a == b); }
};

enum class GameStatus : std::uint8_t { Playing, CheckmateWhite, CheckmateBlack, Stalemate, Draw };

class ChessModel {
public:
    ChessModel() { reset(); }

    void reset();

    ChessColor sideToMove() const { return side_; }
    GameStatus status() const { return status_; }
    Piece pieceAt(Square s) const;
    Piece pieceAt(int file, int rank) const;

    Square selected() const { return selected_; }
    const std::vector<Square>& legalTargets() const { return legalTargets_; }

    bool inCheck() const;
    std::string statusLine() const;

    // 由 Controller 传入棋盘格子坐标（已由 View 从屏幕转换）
    void handleBoardClick(int file, int rank);

private:
    Piece board_[8][8]{};
    ChessColor side_ = ChessColor::White;
    GameStatus status_ = GameStatus::Playing;

    // 王车易位权利：白短/白长/黑短/黑长
    bool castleWK_ = true, castleWQ_ = true, castleBK_ = true, castleBQ_ = true;
    Square epTarget_{-1, -1};  // 过路兵目标格（若无则为 invalid）

    Square selected_{-1, -1};
    std::vector<Square> legalTargets_;

    void recomputeStatus();
    void clearSelection();
    void selectSquare(Square sq);
    void tryMove(Square src, Square dst);

    bool applyMove(Square src, Square dst, PieceType promoteTo);
    void undoMove();  // 用于检测“送王”时试探走子

    struct MoveUndo {
        Square fromSq{};  // 不用名 from：Windows 头文件可能将 from 定义为宏
        Square toSq{};
        Piece mover{};
        Piece victim{};
        bool wasEnPassant = false;
        Square epRemoved{-1, -1};
        bool castleWK = false, castleWQ = false, castleBK = false, castleBQ = false;
        Square epBefore{-1, -1};
        ChessColor sideBefore = ChessColor::White;
    };
    std::vector<MoveUndo> undoStack_;

    bool kingInCheck(ChessColor who) const;
    bool squareAttacked(Square sq, ChessColor byAttacker) const;
    void collectLegalMovesFrom(Square src, std::vector<Square>& out) const;
    void collectPseudoLegal(Square src, std::vector<Square>& out) const;
    bool hasAnyLegalMove(ChessColor who) const;

    static ChessColor opposite(ChessColor c) {
        return c == ChessColor::White ? ChessColor::Black : ChessColor::White;
    }
};

/*
 * =============================================================================
 * MVC — View（视图层）
 * -----------------------------------------------------------------------------
 * 只负责“画出来”：棋盘、棋子、高亮、状态文字。只读 ChessModel，不修改规则数据。
 * 提供屏幕坐标到棋盘 file/rank 的转换，供 Controller 把鼠标事件交给 Model。
 * =============================================================================
 */
#pragma once

#include "raylib.h"
#include "model/ChessModel.h"

class ChessView {
public:
    ChessView() = default;

    void draw(const ChessModel& model) const;

    // 将屏幕像素映射到棋盘格子；false 表示点击在棋盘外
    bool screenToBoard(Vector2 screen, int& outFile, int& outRank) const;

private:
    //static constexpr float kMargin = 40.0f;
    static constexpr float kMargin = 60.0f;
    //static constexpr float kCell = 70.0f;
    static constexpr float kCell = 140.0f;
    static constexpr float kBoardSize = kCell * 8.0f;

    void drawBoardGeometry() const;
    void drawPiece(int file, int rank, Piece p) const;
    static Color raylibTintForPiece(Piece p);
    static const char* pieceLetter(PieceType t);
};

/*
 * 程序入口：组装 MVC（模型 / 视图 / 控制），并驱动 raylib 主循环。
 *
 * - Model:  ChessModel  — 棋局与规则
 * - View:   ChessView   — 绘制与坐标转换
 * - Controller: ChessController — 输入到模型的桥梁
 */

#include "controller/ChessController.h"
#include "model/ChessModel.h"
#include "view/ChessView.h"
#include "raylib.h"

int main() {
    const int winW = 1260;
    const int winH = 1400;
    InitWindow(winW, winH, "Chess — raylib + MVC");
    SetTargetFPS(60);

    ChessModel model;
    ChessView view;
    ChessController controller(model, view);

    while (!WindowShouldClose()) {
        controller.update();

        BeginDrawing();
        ClearBackground(Color{245, 245, 250, 255});
        view.draw(model);
        EndDrawing();
    }

    CloseWindow();
    return 0;
}

/*
 * =============================================================================
 * MVC — Controller（控制层）实现
