struct OnsetInfo {
    float time;
    float energy;
    float centroid;    // spectral centroid (low=0, high=1)
    float bassRatio;   // low frequency energy ratio
};

static bool detectBPM(const std::string& path, float& bpm) {
    aubio_source_t* src = new_aubio_source(path.c_str(), 0, 1024);
    if (!src) return false;
    uint_t sr = aubio_source_get_samplerate(src);

    aubio_tempo_t* tempo = new_aubio_tempo("default", 1024, 512, sr);
    fvec_t* buf = new_fvec(1024);
    fvec_t* beatOut = new_fvec(2);

    bpm = 140;
    std::vector<float> beatTimes;

    uint_t read = 0;
    do {
        aubio_source_do(src, buf, &read);
        aubio_tempo_do(tempo, buf, beatOut);
        if (beatOut->data[0] != 0)
            beatTimes.push_back(aubio_tempo_get_last_s(tempo));
    } while (read == 1024);

    if (beatTimes.size() >= 4) {
        std::vector<float> intervals;
        for (size_t i = 1; i < beatTimes.size(); i++)
            intervals.push_back(beatTimes[i] - beatTimes[i - 1]);
        std::sort(intervals.begin(), intervals.end());
        float median = intervals[intervals.size() / 2];
        if (median > 0.1f) bpm = 60.0f / median;
    }
    bpm = fmaxf(60, fminf(300, bpm));

    del_fvec(buf);
    del_fvec(beatOut);
    del_aubio_tempo(tempo);
    del_aubio_source(src);
    return true;
}

static void detectOnsets(const std::string& path, std::vector<OnsetInfo>& out) {
    aubio_source_t* src = new_aubio_source(path.c_str(), 0, 512);
    if (!src) return;
    uint_t sr = aubio_source_get_samplerate(src);

    aubio_onset_t* od = new_aubio_onset("default", 512, 256, sr);
    fvec_t* buf = new_fvec(512);
    fvec_t* onsetOut = new_fvec(1);

    // FFT for spectral analysis
    aubio_fft_t* fft = new_aubio_fft(512);
    fvec_t* fftOut = new_fvec(256);
    cvec_t* fftC = new_cvec(512);

    uint_t read = 0;
    float lastOnset = -1;
    do {
        aubio_source_do(src, buf, &read);
        aubio_onset_do(od, buf, onsetOut);

        if (onsetOut->data[0] != 0) {
            float t = aubio_onset_get_last_s(od);
            if (t - lastOnset > 0.08f) {
                OnsetInfo info;
                info.time = t;

                // Compute spectral features at onset
                aubio_fft_do(fft, buf, fftC);

                float totalEnergy = 0, weightedFreq = 0, bassEnergy = 0;
                int bassBins = 256 / 8; // ~first octave
                for (int i = 0; i < 256; i++) {
                    float mag = fftC->norm[i];
                    totalEnergy += mag;
                    weightedFreq += mag * i;
                    if (i < bassBins) bassEnergy += mag;
                }
                info.energy = totalEnergy;
                info.centroid = (totalEnergy > 0) ? weightedFreq / totalEnergy / 256.0f : 0.5f;
                info.bassRatio = (totalEnergy > 0) ? bassEnergy / totalEnergy : 0.5f;

                out.push_back(info);
                lastOnset = t;
            }
        }
    } while (read == 512);

    del_fvec(buf);
    del_fvec(onsetOut);
    del_aubio_onset(od);
    del_aubio_fft(fft);
    del_fvec(fftOut);
    del_cvec(fftC);
    del_aubio_source(src);
}

bool ChartGenerator::analyze(const std::string& audioPath, AudioFeatures& out) {
    if (!detectBPM(audioPath, out.bpm)) return false;

    std::vector<OnsetInfo> onsets;
    detectOnsets(audioPath, onsets);
    if (onsets.empty()) return false;

    // Normalize energy to 0-1 range
    float maxEnergy = 0;
    for (auto& o : onsets) if (o.energy > maxEnergy) maxEnergy = o.energy;
    if (maxEnergy > 0)
        for (auto& o : onsets) o.energy /= maxEnergy;

    float beatDur = 60.0f / out.bpm;
    int numLanes = 6;
    float lastGridTime = -1;
    int lastLane = -1;
    int noteIndex = 0;

    // Seed random from song characteristics
    unsigned int seed = (unsigned int)(out.bpm * 100) + (unsigned int)onsets.size();
    auto rng = [seed]() mutable { seed = seed * 1103515245 + 12345; return (seed >> 16) & 0x7fff; };

    for (size_t i = 0; i < onsets.size(); i++) {
        float t = onsets[i].time;
        if (t < 4.0f) continue;

        // Uniform grid: 1/2 beat
        float grid = roundf(t / (beatDur * 0.5f)) * beatDur * 0.5f;

        // Skip if too close to previous note
        if (fabsf(grid - lastGridTime) < beatDur * 0.4f) continue;
        lastGridTime = grid;

        // ── Lane assignment based on spectral features ──
        int lane;
        float centroid = onsets[i].centroid;
        float bass = onsets[i].bassRatio;
        float energy = onsets[i].energy;

        if (bass > 0.5f) {
            lane = (centroid < 0.15f) ? 0 : 1;
        } else if (centroid > 0.6f) {
            lane = (centroid > 0.75f) ? 5 : 4;
        } else {
            lane = (centroid > 0.35f) ? 3 : 2;
        }

        // Variation by section
        int section = (int)(t / (beatDur * 8));
        int variation = (rng() % 3) - 1;

        switch (section % 5) {
        case 0: break;
        case 1: lane += variation; break;
        case 2: lane = (noteIndex * 2 + 3) % numLanes; break;
        case 3: lane += (variation * 2); break;
        case 4: lane = numLanes - 1 - lane; break;
        }

        lane = fmaxf(0, fminf(numLanes - 1, lane));
        if (lane == lastLane) {
            int tries = 0;
            do { lane = (lane + 1 + rng() % (numLanes - 1)) % numLanes; tries++; }
            while (lane == lastLane && tries < 5);
        }
        lastLane = lane;

        // ── Hold notes for sustained sounds ──
        bool makeHold = false;
        float holdEnd = 0;
        if (energy < 0.4f && bass > 0.3f && noteIndex % 10 == 0) {
            makeHold = true;
            holdEnd = grid + beatDur * (1 + (rng() % 3));
        }

        out.notes.push_back({grid, lane, makeHold, holdEnd});
        noteIndex++;
    }

    // Post-process: remove taps that overlap with holds on the same lane
    // Sort by time
    std::sort(out.notes.begin(), out.notes.end(),
              [](const GenNote& a, const GenNote& b) {
                  return a.time < b.time || (a.time == b.time && a.lane < b.lane);
              });

    // Build hold occupancy ranges per lane
    struct HoldRange { float start; float end; int lane; };
    std::vector<HoldRange> holds;
    for (auto& n : out.notes) {
        if (n.isHold)
            holds.push_back({n.time, n.holdEnd, n.lane});
    }

    // Remove taps that fall inside any hold range on the same lane
    out.notes.erase(
        std::remove_if(out.notes.begin(), out.notes.end(),
            [&](const GenNote& n) {
                if (n.isHold) return false;
                for (auto& h : holds) {
                    if (n.lane == h.lane && n.time >= h.start - 0.01f && n.time <= h.end + 0.01f)
                        return true;
                }
                return false;
            }),
        out.notes.end());

    // Deduplicate same time+lane
    out.notes.erase(std::unique(out.notes.begin(), out.notes.end(),
                                [](const GenNote& a, const GenNote& b) {
                                    return fabsf(a.time - b.time) < 0.01f && a.lane == b.lane;
                                }),
                    out.notes.end());

    return !out.notes.empty();
}

std::string ChartGenerator::baseName(const std::string& path) {
    size_t slash = path.find_last_of("/\\");
    std::string name = (slash == std::string::npos) ? path : path.substr(slash + 1);
    size_t dot = name.find_last_of('.');
    return (dot == std::string::npos) ? name : name.substr(0, dot);
}

#include "Game.h"
#include "FilePicker.h"
#include <cmath>
#include <cstring>
#include <algorithm>

void Game::run() {
    InitWindow(Config::SW, Config::SH, "aeacrA");
    InitAudioDevice();
    SetTargetFPS(60);

    audio_.init();
    renderer_.init();
    songMgr_.scanSongs();

    while (!WindowShouldClose()) {
        float dt = GetFrameTime();
        bgPhase_ += dt * 0.5f;
        audio_.updateMusic();

        switch (state_) {
        case GameState::MENU:     tickMenu(); break;
        case GameState::SELECT:   tickSelect(); break;
        case GameState::IMPORTING: tickImporting(); break;
        case GameState::PLAYING:  tickPlaying(dt); break;
        case GameState::RESULT:   tickResult(); break;
        }
    }

    renderer_.shutdown();
    audio_.cleanup();
    CloseWindow();
}

void Game::startGame() {
    state_ = GameState::PLAYING;
    gameTime_ = 0;
    memset(laneFlash_, 0, sizeof(laneFlash_));
    comboScale_ = 1; screenFlash_ = 0; beatPulse_ = 0;
    lastJudgeTime_ = -1; lastJudge_ = JudgeResult::NONE;
    judge_.reset();
    particles_.clear();

    audio_.stopMusic();

    if (!chart_.loadFromFile(chartPath_))
        chart_.generate();

    std::string ap;
    for (auto& s : songMgr_.songs()) {
        if (s.filePath == chartPath_) { ap = s.audioPath; break; }
    }
    if (ap.empty()) ap = songMgr_.audioPathFor({"", chartPath_, 0, ""});
    if (!ap.empty()) audio_.loadMusic(ap);
    musicStarted_ = false;

    audio_.resetBeat();
}

void Game::tickMenu() {
    renderer_.beginFrame();
    renderer_.drawMenu(bgPhase_);
    renderer_.endFrame();
    if (input_.enterPressed()) {
        state_ = GameState::SELECT;
        selectedSong_ = 0;
        selectScroll_ = 0;
        selectJustEntered_ = true;
    }
}

void Game::tickSelect() {
    if (selectJustEntered_) {
        selectJustEntered_ = false;
        renderer_.beginFrame();
        renderer_.drawSelect(bgPhase_, songMgr_.songs(), selectedSong_, selectScroll_, true);
        renderer_.endFrame();
        return;
    }

    if (input_.escapePressed()) { state_ = GameState::MENU; return; }

    if (IsKeyPressed(KEY_I)) {
        state_ = GameState::IMPORTING;
        importStatus_ = "";
        importProgress_ = 0;
        return;
    }

    if (IsKeyPressed(KEY_UP) || IsKeyPressed(KEY_W)) {
        selectedSong_ = (selectedSong_ - 1 + (int)songMgr_.songs().size()) % (int)songMgr_.songs().size();
    }
    if (IsKeyPressed(KEY_DOWN) || IsKeyPressed(KEY_S)) {
        selectedSong_ = (selectedSong_ + 1) % (int)songMgr_.songs().size();
    }
    selectScroll_ += (selectedSong_ * 70.0f - selectScroll_) * 0.2f;

    if (input_.enterPressed()) {
        chartPath_ = songMgr_.songs()[selectedSong_].filePath;
        autoplay_ = false;
        startGame();
        return;
    }

    // Press A for auto-demo of selected song
    if (IsKeyPressed(KEY_A)) {
        chartPath_ = songMgr_.songs()[selectedSong_].filePath;
        autoplay_ = true;
        startGame();
        return;
    }

    renderer_.beginFrame();
    renderer_.drawSelect(bgPhase_, songMgr_.songs(), selectedSong_, selectScroll_, true);
    renderer_.endFrame();
}

void Game::tickImporting() {
    renderer_.beginFrame();
    renderer_.drawImport(bgPhase_, importStatus_.c_str(), importProgress_);
    renderer_.endFrame();

    if (importStatus_.empty()) {
        importStatus_ = "Opening file dialog...";
        importProgress_ = 0.1f;
        renderer_.beginFrame();
        renderer_.drawImport(bgPhase_, importStatus_.c_str(), importProgress_);
        renderer_.endFrame();

        std::string path = openAudioFileDialog();
        if (path.empty()) {
            importStatus_ = "Cancelled. Press any key...";
            importProgress_ = -1;
            return;
        }

        importStatus_ = "Analyzing audio...";
        importProgress_ = 0.3f;
        renderer_.beginFrame();
        renderer_.drawImport(bgPhase_, importStatus_.c_str(), importProgress_);
        renderer_.endFrame();

        std::string outChart;
        if (songMgr_.importAudio(path, outChart)) {
            importStatus_ = "Import complete! Press ENTER.";
            importProgress_ = 1.0f;
            songMgr_.scanSongs();
            auto& songs = songMgr_.songs();
            for (size_t i = 0; i < songs.size(); i++) {
                if (songs[i].filePath == outChart) {
                    selectedSong_ = (int)i;
                    break;
                }
            }
        } else {
            importStatus_ = "Import failed! Press any key.";
            importProgress_ = -1;
        }
        return;
    }

    if (importProgress_ >= 1.0f) {
        if (input_.enterPressed()) {
            selectJustEntered_ = true;
            state_ = GameState::SELECT;
        }
    } else if (importProgress_ < 0) {
        if (input_.enterPressed() || input_.escapePressed()) {
            selectJustEntered_ = true;
            state_ = GameState::SELECT;
        }
    }
}

void Game::tickResult() {
    renderer_.beginFrame();
    renderer_.drawResults(bgPhase_, judge_.score(), judge_.maxCombo(),
                          std::array<int,4>{judge_.count(JudgeResult::PERFECT),
                                            judge_.count(JudgeResult::GREAT),
                                            judge_.count(JudgeResult::GOOD),
                                            judge_.count(JudgeResult::MISS)}.data(),
                          chart_.size());
    renderer_.endFrame();
    if (input_.enterPressed()) state_ = GameState::MENU;
}

void Game::tickPlaying(float dt) {
    audio_.updateMusic();
    gameTime_ += dt;

    if (!musicStarted_ && gameTime_ >= 4.0f && audio_.hasMusic()) {
        audio_.playMusic();
        musicStarted_ = true;
    }

    float pulse = audio_.updateBeat(gameTime_);
    if (pulse > 0) beatPulse_ = pulse;

    for (int i = 0; i < Config::LANES; i++)
        laneFlash_[i] *= powf(0.005f, dt);
    comboScale_ = fmaxf(1, comboScale_ + (1 - comboScale_) * (1 - powf(0.02f, dt)));
    screenFlash_ *= powf(0.01f, dt);
    beatPulse_ *= powf(0.02f, dt);

    particles_.update(dt);

    // ── Miss expired notes ──
    for (size_t i = 0; i < chart_.size(); i++) {
        Note& n = chart_.note(i);
        if (n.result != JudgeResult::NONE) continue;
        if (n.type == NoteType::TAP && gameTime_ > n.time + Config::JW_GOOD) {
            n.result = JudgeResult::MISS;
            judge_.apply(JudgeResult::MISS);
            lastJudge_ = JudgeResult::MISS;
            lastJudgeTime_ = gameTime_;
        } else if (n.type == NoteType::HOLD && gameTime_ > n.time + Config::JW_GOOD) {
            n.result = JudgeResult::MISS;
            n.holdResult = JudgeResult::MISS;
            judge_.applyHold(JudgeResult::MISS, JudgeResult::MISS);
            lastJudge_ = JudgeResult::MISS;
            lastJudgeTime_ = gameTime_;
        }
    }

    // ── Auto-complete held notes past end time ──
    for (size_t i = 0; i < chart_.size(); i++) {
        Note& n = chart_.note(i);
        if (n.type != NoteType::HOLD || !n.holding || n.holdResult != JudgeResult::NONE) continue;
        if (gameTime_ >= n.endTime) {
            float tailDiff = fabsf(gameTime_ - n.endTime);
            JudgeResult tailJ = judge_.judge(tailDiff);
            if (tailJ == JudgeResult::NONE) tailJ = JudgeResult::GOOD;
            n.holdResult = tailJ;
            n.holding = false;
            judge_.applyHold(n.result, tailJ);
            comboScale_ = 1.5f;
            if (tailJ == JudgeResult::PERFECT) screenFlash_ = 0.5f;
            float hx = Config::FIELD_X + (n.lane + 0.5f) * Config::LANE_W;
            particles_.spawnExplosion(hx, Config::HIT_Y, n.lane);
        }
    }

    // ── Input handling: autoplay or manual ──
    if (autoplay_) {
        for (size_t i = 0; i < chart_.size(); i++) {
            Note& n = chart_.note(i);
            if (n.result != JudgeResult::NONE) continue;
            float diff = n.time - gameTime_;

            // Tap note: auto-hit at perfect timing
            if (n.type == NoteType::TAP && diff <= 0.005f && diff > -Config::JW_PERFECT) {
                n.result = JudgeResult::PERFECT;
                judge_.apply(JudgeResult::PERFECT);
                comboScale_ = 1.8f; lastJudge_ = JudgeResult::PERFECT;
                lastJudgeTime_ = gameTime_; screenFlash_ = 1;
                laneFlash_[n.lane] = 1; keysDown_[n.lane] = true;
                audio_.playLane(n.lane);
                float hx = Config::FIELD_X + (n.lane + 0.5f) * Config::LANE_W;
                particles_.spawnExplosion(hx, Config::HIT_Y, n.lane);
                particles_.spawnSpiral(hx, Config::HIT_Y, gameTime_, n.lane);
                if (judge_.combo() > 10) particles_.spawnFire(hx, Config::HIT_Y);
            }

            // Hold head: auto-hit
            if (n.type == NoteType::HOLD && !n.holding && n.holdResult == JudgeResult::NONE
                && diff <= 0.005f && diff > -Config::JW_PERFECT) {
                n.result = JudgeResult::PERFECT; n.holding = true;
                judge_.apply(JudgeResult::PERFECT);
                comboScale_ = 1.8f; lastJudge_ = JudgeResult::PERFECT;
                lastJudgeTime_ = gameTime_; screenFlash_ = 1;
                laneFlash_[n.lane] = 1; keysDown_[n.lane] = true;
                audio_.playLane(n.lane);
                float hx = Config::FIELD_X + (n.lane + 0.5f) * Config::LANE_W;
                particles_.spawnExplosion(hx, Config::HIT_Y, n.lane);
                particles_.spawnSpiral(hx, Config::HIT_Y, gameTime_, n.lane);
                if (judge_.combo() > 10) particles_.spawnFire(hx, Config::HIT_Y);
            }

            // Hold tail: auto-release at perfect timing
            if (n.type == NoteType::HOLD && n.holding && n.holdResult == JudgeResult::NONE
                && gameTime_ >= n.endTime - 0.005f) {
                n.holdResult = JudgeResult::PERFECT; n.holding = false;
                keysDown_[n.lane] = false;
                judge_.applyHold(n.result, JudgeResult::PERFECT);
                comboScale_ = 1.5f; screenFlash_ = 0.5f;
                float hx = Config::FIELD_X + (n.lane + 0.5f) * Config::LANE_W;
                particles_.spawnExplosion(hx, Config::HIT_Y, n.lane);
            }
        }

        // Release auto-held keys no longer needed
        for (int i = 0; i < Config::LANES; i++) {
            bool needed = false;
            for (size_t j = 0; j < chart_.size(); j++)
                if (chart_.note(j).lane == i && chart_.note(j).holding) { needed = true; break; }
            if (!needed) keysDown_[i] = false;
        }
    } else {
        // Manual play
        for (int lane : input_.pressedLanes()) {
            laneFlash_[lane] = 1;
            Note* best = nullptr;
            float bd = 999;
            for (size_t i = 0; i < chart_.size(); i++) {
                Note& n = chart_.note(i);
                if (n.lane != lane || n.result != JudgeResult::NONE) continue;
                float d = fabsf(gameTime_ - n.time);
                if (d < bd && d < Config::JW_GOOD) { best = &n; bd = d; }
            }
            if (best) {
                JudgeResult j = judge_.judge(bd);
                best->result = j;
                if (best->type == NoteType::HOLD) best->holding = true;
                judge_.apply(j);
                comboScale_ = 1.8f;
                lastJudge_ = j; lastJudgeTime_ = gameTime_;
                if (j == JudgeResult::PERFECT) screenFlash_ = 1;
                audio_.playLane(lane);
                float hx = Config::FIELD_X + (lane + 0.5f) * Config::LANE_W;
                particles_.spawnExplosion(hx, Config::HIT_Y, lane);
                particles_.spawnSpiral(hx, Config::HIT_Y, gameTime_, lane);
                if (judge_.combo() > 10) particles_.spawnFire(hx, Config::HIT_Y);
            } else {
                judge_.apply(JudgeResult::MISS);
                lastJudge_ = JudgeResult::MISS;
                lastJudgeTime_ = gameTime_;
                comboScale_ = 1.2f;
            }
        }

        for (int lane : input_.releasedLanes()) {
            Note* activeHold = nullptr;
            for (size_t i = 0; i < chart_.size(); i++) {
                Note& n = chart_.note(i);
                if (n.type == NoteType::HOLD && n.lane == lane && n.holding && n.holdResult == JudgeResult::NONE) {
                    activeHold = &n; break;
                }
            }
            if (activeHold) {
                float tailDiff = fabsf(gameTime_ - activeHold->endTime);
                JudgeResult tailJ = tailDiff < Config::JW_GOOD ? judge_.judge(tailDiff) : JudgeResult::MISS;
                activeHold->holdResult = tailJ;
                activeHold->holding = false;
                judge_.applyHold(activeHold->result, tailJ);
                comboScale_ = 1.5f;
                if (tailJ == JudgeResult::PERFECT) screenFlash_ = 0.5f;
                lastJudge_ = tailJ; lastJudgeTime_ = gameTime_;
                float hx = Config::FIELD_X + (lane + 0.5f) * Config::LANE_W;
                particles_.spawnExplosion(hx, Config::HIT_Y, lane);
            }
        }

        for (int i = 0; i < Config::LANES; i++)
            keysDown_[i] = input_.isKeyDown(i);
    }

    if (input_.escapePressed()) { audio_.stopMusic(); autoplay_ = false; state_ = GameState::MENU; return; }
    if (chart_.allDone()) { audio_.stopMusic(); autoplay_ = false; state_ = GameState::RESULT; return; }

    float progress = chart_.size() > 0 ? (float)chart_.doneCount() / (float)chart_.size() : 1;

    renderer_.beginFrame();
    renderer_.drawBackground(bgPhase_, dt);
    renderer_.drawTrackBase(beatPulse_);
    renderer_.drawLanes(laneFlash_, beatPulse_);
    renderer_.drawBeatLines(gameTime_);
    renderer_.drawNotes(chart_.notes(), gameTime_);
    renderer_.drawHitLine(beatPulse_, laneFlash_);
    renderer_.drawReceptors(laneFlash_, keysDown_);
    renderer_.drawParticles(particles_.particles());
    renderer_.drawScreenFlash(screenFlash_);
    renderer_.drawJudgment(lastJudge_, gameTime_ - lastJudgeTime_);
    renderer_.drawUI(judge_.score(), judge_.combo(), comboScale_, progress);
    if (gameTime_ < 4.0f) {
        int count = (int)(4.0f - gameTime_);
        if (count > 4) count = 4;
        renderer_.drawCountdown(count);
    }
    if (autoplay_)
        renderer_.drawDemoOverlay(chart_.title(), bgPhase_);
    renderer_.endFrame();
}

#include "InputManager.h"

std::vector<int> InputManager::pressedLanes() const {
    std::vector<int> lanes;
    for (int i = 0; i < Config::LANES; i++)
        if (IsKeyPressed(Config::KEY_MAP[i])) lanes.push_back(i);
    return lanes;
}

std::vector<int> InputManager::releasedLanes() const {
    std::vector<int> lanes;
    for (int i = 0; i < Config::LANES; i++)
        if (IsKeyReleased(Config::KEY_MAP[i])) lanes.push_back(i);
    return lanes;
}

bool InputManager::isKeyDown(int lane) const {
    return lane >= 0 && lane < Config::LANES && IsKeyDown(Config::KEY_MAP[lane]);
}

bool InputManager::enterPressed() const { return IsKeyPressed(KEY_ENTER); }
bool InputManager::escapePressed() const { return IsKeyPressed(KEY_ESCAPE); }
bool InputManager::quitRequested() const { return WindowShouldClose(); }

#include "Judge.h"

void JudgeSystem::reset() {
    score_ = 0; combo_ = 0; maxCombo_ = 0;
    counts_[0] = counts_[1] = counts_[2] = counts_[3] = 0;
}

JudgeResult JudgeSystem::judge(float diff) const {
    if (diff <= Config::JW_PERFECT) return JudgeResult::PERFECT;
    if (diff <= Config::JW_GREAT)   return JudgeResult::GREAT;
    if (diff <= Config::JW_GOOD)    return JudgeResult::GOOD;
    return JudgeResult::NONE;
}

static int idx(JudgeResult j) {
    return (j == JudgeResult::PERFECT) ? 0 :
           (j == JudgeResult::GREAT)   ? 1 :
           (j == JudgeResult::GOOD)    ? 2 : 3;
}

static int pts(JudgeResult j) {
    if (j == JudgeResult::PERFECT) return 350;
    if (j == JudgeResult::GREAT)   return 200;
    if (j == JudgeResult::GOOD)    return 100;
    return 0;
}

void JudgeSystem::apply(JudgeResult j) {
    counts_[idx(j)]++;
    score_ += pts(j);
    if (j == JudgeResult::MISS) { combo_ = 0; }
    else { combo_++; if (combo_ > maxCombo_) maxCombo_ = combo_; }
}

void JudgeSystem::applyHold(JudgeResult head, JudgeResult tail) {
    // 头部判定
    apply(head);
    // 尾部加分（hold 的额外奖励）
    if (head != JudgeResult::MISS && tail != JudgeResult::MISS) {
        counts_[idx(tail)]++;
        score_ += pts(tail);
        combo_++; if (combo_ > maxCombo_) maxCombo_ = combo_;
    }
}

int JudgeSystem::count(JudgeResult j) const { return counts_[idx(j)]; }

#include "ParticleSystem.h"
#include <cstdlib>
#include <algorithm>

void ParticleSystem::clear() { particles_.clear(); }

void ParticleSystem::update(float dt) {
    for (auto& p : particles_) {
        p.pos.x += p.vel.x * dt;
        p.pos.y += p.vel.y * dt;
        p.vel.y += 400.0f * dt;
        p.vel.x *= 0.97f;
        p.life -= dt;
    }
    particles_.erase(
        std::remove_if(particles_.begin(), particles_.end(),
                       [](const Particle& p) { return p.life <= 0; }),
        particles_.end());
}

void ParticleSystem::spawnExplosion(float x, float y, int lane) {
    for (int i = 0; i < 25; i++) {
        float ang = (float)rand() / RAND_MAX * PI * 2;
        float spd = 50 + (float)rand() / RAND_MAX * 350;
        Color pc = (i % 3 == 0) ? (Color){255, 255, 255, 255}
                   : (i % 3 == 1) ? Config::PASTEL[rand() % 6]
                                  : Config::PASTEL[lane];
        particles_.push_back({{x, y},
                              {cosf(ang) * spd, sinf(ang) * spd - 260},
                              pc,
                              0.35f + (float)(rand() % 30) / 100,
                              0.65f,
                              1.5f + (float)(rand() % 40) / 10,
                              i % 3 == 0});
    }
}

void ParticleSystem::spawnSpiral(float x, float y, float time, int lane) {
    for (int i = 0; i < 8; i++) {
        float ang = (float)i / 8 * PI * 2 + time * 4;
        float spd = 100 + (float)rand() / RAND_MAX * 150;
        particles_.push_back({{x, y},
                              {cosf(ang) * spd, sinf(ang) * spd - 130},
                              Config::PASTEL[(lane + i) % 6],
                              0.5f + (float)(rand() % 20) / 100,
                              0.6f,
                              2.5f + (float)(rand() % 30) / 10,
                              false});
    }
}

void ParticleSystem::spawnFire(float x, float y) {
    for (int i = 0; i < 6; i++) {
        float a = -PI / 2 + ((float)(rand() % 100) / 100 - 0.5f) * 0.4f;
        float s = 180 + (float)(rand() % 180);
        particles_.push_back({{x + (float)(rand() % 60 - 30), y},
                              {cosf(a) * s, sinf(a) * s},
                              Config::PASTEL[rand() % 6],
                              0.3f + (float)(rand() % 20) / 100,
                              0.45f,
                              3 + (float)(rand() % 30) / 10,
                              true});
    }
}

#include "Renderer.h"
#include <cstdlib>
#include <algorithm>

float Renderer::perspY(float d) {
    return Config::VP_Y + Config::TRACK_LEN * powf(fmaxf(d, 0), Config::PERSP);
}
float Renderer::perspX(float hx, float d) {
    return Config::VP_X + (hx - Config::VP_X) * fmaxf(d, 0);
}
float Renderer::noteDepth(const Note& n, float t) {
    return 1.0f - (n.time - t) * Config::SCROLL_SPEED / Config::TRACK_LEN;
}

void Renderer::init() {
    petals_.resize(50);
    for (auto& p : petals_) {
        p.x = (float)(rand() % Config::SW);
        p.y = (float)(rand() % Config::SH);
        p.speed = 5 + (float)(rand() % 15);
        p.size = 2 + (float)(rand() % 100) / 50;
        p.phase = (float)(rand() % 100) / 10;
        p.amp = 15 + (float)(rand() % 30);
        p.tint = Config::PASTEL[rand() % 6];
    }
}
void Renderer::shutdown() {}

void Renderer::drawSparkle(Vector2 pos, float size, Color c) {
    DrawLineV({pos.x - size, pos.y}, {pos.x + size, pos.y}, c);
    DrawLineV({pos.x, pos.y - size}, {pos.x, pos.y + size}, c);
    float d = size * 0.5f;
    DrawLineV({pos.x - d, pos.y - d}, {pos.x + d, pos.y + d}, ColorAlpha(c, 0.4f));
    DrawLineV({pos.x + d, pos.y - d}, {pos.x - d, pos.y + d}, ColorAlpha(c, 0.4f));
}

void Renderer::drawPerspectiveLane(int lane, float flash) {
    const int SEG = 20;
    float lx = Config::FIELD_X + lane * Config::LANE_W;
    float rx = lx + Config::LANE_W;
    Color dim = Config::PASTEL_DIM[lane];
    Color pc = Config::PASTEL[lane];
    for (int s = 0; s < SEG; s++) {
        float d0 = (float)s / SEG, d1 = (float)(s + 1) / SEG;
        float y0 = perspY(d0), y1 = perspY(d1);
        float al0 = perspX(lx, d0), ar0 = perspX(rx, d0);
        float al1 = perspX(lx, d1), ar1 = perspX(rx, d1);
        float t = d1;
        float fr = dim.r + pc.r * 0.22f * t + flash * pc.r * 0.4f;
        float fg = dim.g + pc.g * 0.22f * t + flash * pc.g * 0.4f;
        float fb = dim.b + pc.b * 0.22f * t + flash * pc.b * 0.4f;
        Color c = {(unsigned char)fminf(255, fr), (unsigned char)fminf(255, fg),
                   (unsigned char)fminf(255, fb), 255};
        DrawTriangle({al0, y0}, {ar0, y0}, {al1, y1}, c);
        DrawTriangle({ar0, y0}, {ar1, y1}, {al1, y1}, c);
    }
}

void Renderer::beginFrame() { BeginDrawing(); }
void Renderer::endFrame() { EndDrawing(); }

void Renderer::drawBackground(float bgPhase, float dt) {
    ClearBackground(Config::BG_CREAM);
    for (auto& p : petals_) {
        p.y -= p.speed * dt;
        p.x += sinf(bgPhase + p.phase) * p.amp * dt;
        if (p.y < -10) { p.y = Config::SH + 10; p.x = (float)(rand() % Config::SW); }
        float a = 0.12f + sinf(bgPhase * 2 + p.phase) * 0.08f;
        DrawCircleV({p.x, p.y}, p.size * 1.5f, ColorAlpha(p.tint, a * 0.3f));
        DrawCircleV({p.x, p.y}, p.size, ColorAlpha(p.tint, a));
    }
    for (int ring = 0; ring < 2; ring++) {
        float br = 90 + ring * 55;
        int n = 6 + ring * 3;
        for (int i = 0; i < n; i++) {
            float ang = bgPhase * (0.12f + ring * 0.06f) + (float)i / n * PI * 2;
            float r = br + sinf(bgPhase + i + ring) * 10;
            float cx = Config::SW / 2 + cosf(ang) * r;
            float cy = Config::SH * 0.3f + sinf(ang) * r * 0.35f;
            DrawCircleLines((int)cx, (int)cy, 12 + ring * 8,
                            ColorAlpha(Config::PASTEL[(i + ring) % 6], 0.07f));
        }
    }
}

void Renderer::drawTrackBase(float beatPulse) {
    for (int i = 5; i >= 0; i--) {
        float r = 15 + i * 20;
        float a = 0.05f * (6 - i) * (0.5f + beatPulse * 0.3f);
        DrawCircleV({Config::VP_X, Config::VP_Y}, r, ColorAlpha(Config::ROSE_GOLD, a));
    }
    float margin = 8.0f;
    float bl = Config::FIELD_X - margin, br = Config::FIELD_X + Config::LANES * Config::LANE_W + margin;
    for (int s = 0; s < 16; s++) {
        float d0 = (float)s / 16, d1 = (float)(s + 1) / 16;
        float y0 = perspY(d0), y1 = perspY(d1);
        float l0 = perspX(bl, d0), r0 = perspX(br, d0);
        float l1 = perspX(bl, d1), r1 = perspX(br, d1);
        unsigned char a = (unsigned char)(40 + d1 * 50);
        DrawTriangle({l0, y0}, {r0, y0}, {l1, y1}, {20, 15, 25, a});
        DrawTriangle({r0, y0}, {r1, y1}, {l1, y1}, {20, 15, 25, a});
    }
}

void Renderer::drawLanes(const float laneFlash[], float beatPulse) {
    for (int i = 0; i < Config::LANES; i++)
        drawPerspectiveLane(i, laneFlash[i]);
    for (int i = 0; i <= Config::LANES; i++) {
        float ex = Config::FIELD_X + i * Config::LANE_W;
        DrawLineEx({Config::VP_X, Config::VP_Y}, {ex, Config::HIT_Y},
                   1.5f, ColorAlpha(Config::ROSE_GOLD, 0.45f));
    }
    float slx = Config::FIELD_X - 10, srx = Config::FIELD_X + Config::LANES * Config::LANE_W + 10;
    for (int i = 0; i < 5; i++) {
        float d = 0.2f + (float)i * 0.16f;
        if (d > 1) break;
        float y = perspY(d);
        DrawCircleV({perspX(slx, d), y}, 2.5f, ColorAlpha(Config::ROSE_GOLD, d * 0.15f));
        DrawCircleV({perspX(srx, d), y}, 2.5f, ColorAlpha(Config::ROSE_GOLD, d * 0.15f));
    }
}

void Renderer::drawBeatLines(float gameTime) {
    float bp = fmodf(gameTime, Config::BEAT) / Config::BEAT;
    for (int b = 0; b < 14; b++) {
        float d = bp + (float)b * 0.5f;
        if (d < 0.02f || d > 1) continue;
        float y = perspY(d);
        float lx = perspX(Config::FIELD_X, d);
        float rx = perspX(Config::FIELD_X + Config::LANES * Config::LANE_W, d);
        DrawLine((int)lx, (int)y, (int)rx, (int)y, ColorAlpha(Config::ROSE_GOLD, d * 0.08f));
    }
}

void Renderer::drawNotes(const std::vector<Note>& notes, float gameTime) {
    for (auto& n : notes) {
        if (n.finished()) continue;

        float depth = noteDepth(n, gameTime);
        if (depth < -0.1f) continue;

        float cd = fmaxf(0.01f, fminf(depth, 1.2f));
        float ncx = Config::FIELD_X + (n.lane + 0.5f) * Config::LANE_W;
        float nx = perspX(ncx, cd);
        float nw = Config::LANE_W * 0.85f * cd;
        float nh = fmaxf(2, 14 * cd);
        Color pc = Config::PASTEL[n.lane];
        float glow = cd * cd;

        if (n.type == NoteType::HOLD) {
            // ── Hold 音符 ──
            float endDepth = 1.0f - (n.endTime - gameTime) * Config::SCROLL_SPEED / Config::TRACK_LEN;
            float headD = fmaxf(0.01f, fminf(cd, 1.0f));
            float tailD = fmaxf(0.01f, fminf(endDepth, 1.0f));

            // 身体（渐变条带）
            int seg = 28;
            for (int s = 0; s < seg; s++) {
                float t0 = (float)s / seg, t1 = (float)(s + 1) / seg;
                float d0 = headD + (tailD - headD) * t0;
                float d1 = headD + (tailD - headD) * t1;
                if (d1 < 0.01f) continue;
                d0 = fmaxf(0.01f, d0); d1 = fmaxf(0.01f, d1);

                float y0 = perspY(d0), y1 = perspY(d1);
                float sx0 = perspX(ncx, d0), sx1 = perspX(ncx, d1);
                float w0 = nw * (1 - t0 * 0.6f), w1 = nw * (1 - t1 * 0.6f);

                float segAlpha = glow * 0.35f;
                // 正在按住时更亮
                if (n.holding) segAlpha = glow * 0.55f;

                Color bc = n.holding ?
                    ColorAlpha((Color){(unsigned char)fminf(255, pc.r + 60),
                                       (unsigned char)fminf(255, pc.g + 60),
                                       (unsigned char)fminf(255, pc.b + 60), 255}, segAlpha * 0.6f)
                    : ColorAlpha(pc, segAlpha * 0.5f);
                DrawTriangle({sx0 - w0 / 2, y0}, {sx0 + w0 / 2, y0}, {sx1 - w1 / 2, y1}, bc);
                DrawTriangle({sx0 + w0 / 2, y0}, {sx1 + w1 / 2, y1}, {sx1 - w1 / 2, y1}, bc);

                // 中心亮线
                float cw0 = w0 * 0.12f, cw1 = w1 * 0.12f;
                DrawTriangle({sx0 - cw0, y0}, {sx0 + cw0, y0}, {sx1 - cw1, y1},
                             ColorAlpha(WHITE, segAlpha * 0.6f));
                DrawTriangle({sx0 + cw0, y0}, {sx1 + cw1, y1}, {sx1 - cw1, y1},
                             ColorAlpha(WHITE, segAlpha * 0.6f));
            }

            // 头部（和 tap 一样）
            float hy = perspY(headD);
            float hx = perspX(ncx, headD);
            float hw = Config::LANE_W * 0.85f * headD;
            float hh = fmaxf(2, 14 * headD);
            for (int g = 5; g >= 0; g--) {
                float ew = hw + g * 8 * headD, eh = hh + g * 5 * headD;
                DrawRectangleRec({hx - ew / 2, hy - eh / 2, ew, eh},
                                 ColorAlpha(pc, glow * 0.04f * (6 - g)));
            }
            DrawRectangleRec({hx - hw * 0.5f, hy - hh * 0.5f, hw, hh}, ColorAlpha(pc, glow * 0.8f));
            DrawRectangleRec({hx - hw * 0.35f, hy - hh * 0.35f, hw * 0.7f, hh * 0.7f},
                             ColorAlpha(WHITE, glow * 0.6f));

            // 尾部标记
            if (tailD > 0.01f && tailD < 1.1f) {
                float ty = perspY(tailD);
                float tx = perspX(ncx, tailD);
                float tw = Config::LANE_W * 0.7f * tailD;
                DrawRectangleRec({tx - tw / 2, ty - 3, tw, 6},
                                 ColorAlpha(pc, glow * 0.7f));
                DrawRectangleRec({tx - tw * 0.15f, ty - 2, tw * 0.3f, 4},
                                 ColorAlpha(WHITE, glow * 0.9f));
            }
        } else {
            // ── Tap 音符 ──
            if (depth > 1.15f) continue;
            // 光带尾巴
            for (int s = 20; s >= 0; s--) {
                float prog = (float)s / 20;
                float sd = cd - prog * 0.18f;
                if (sd < 0.01f) continue;
                float sy = perspY(sd);
                float sx = perspX(ncx, sd) + sinf(prog * PI * 4 - gameTime * 10) * 3.0f * (1 - prog) * cd;
                float sw = nw * (1 - prog * 0.85f);
                float sh = fmaxf(1, 4 * sd);
                float sa = (1 - prog * prog) * glow * 0.5f;
                DrawRectangleRec({sx - sw * 0.9f, sy - sh, sw * 1.8f, sh * 2}, ColorAlpha(pc, sa * 0.25f));
                DrawRectangleRec({sx - sw * 0.2f, sy - sh * 0.3f, sw * 0.4f, sh * 0.6f}, ColorAlpha(WHITE, sa * 0.5f));
            }
            // 头部
            for (int g = 6; g >= 0; g--) {
                float ew = nw + g * 10 * cd, eh = nh + g * 7 * cd;
                DrawRectangleRec({nx - ew / 2, Config::HIT_Y - (Config::HIT_Y - perspY(cd)) - eh / 2, ew, eh},
                                 ColorAlpha(pc, glow * 0.05f * (7 - g)));
            }
            float ny2 = perspY(cd);
            for (int g = 6; g >= 0; g--) {
                float ew = nw + g * 10 * cd, eh = nh + g * 7 * cd;
                DrawRectangleRec({nx - ew / 2, ny2 - eh / 2, ew, eh}, ColorAlpha(pc, glow * 0.05f * (7 - g)));
            }
            DrawRectangleRec({nx - nw * 0.5f, ny2 - nh * 0.5f, nw, nh}, ColorAlpha(pc, glow * 0.8f));
            DrawRectangleRec({nx - nw * 0.35f, ny2 - nh * 0.35f, nw * 0.7f, nh * 0.7f}, ColorAlpha(WHITE, glow * 0.6f));
            float coreW = nw * 0.18f, coreH = nh * 0.85f;
            DrawRectangleRec({nx - coreW / 2, ny2 - coreH / 2, coreW, coreH}, ColorAlpha(WHITE, glow * 0.95f));
            float dotR = fmaxf(1, 3.5f * cd);
            DrawCircleV({nx - nw * 0.35f, ny2}, dotR, ColorAlpha(Config::ROSE_GOLD, glow * 0.5f));
            DrawCircleV({nx + nw * 0.35f, ny2}, dotR, ColorAlpha(Config::ROSE_GOLD, glow * 0.5f));
        }
    }
}

void Renderer::drawHitLine(float beatPulse, const float laneFlash[]) {
    float le = Config::FIELD_X, re = Config::FIELD_X + Config::LANES * Config::LANE_W;
    for (int g = 4; g >= 0; g--) {
        float ex = (float)(g + 1) * 3;
        float a = (0.3f + beatPulse * 0.3f) * 0.06f * (5 - g);
        DrawRectangle(le - ex, Config::HIT_Y - 1 - ex, re - le + ex * 2, 2 + ex * 2,
                      ColorAlpha(Config::ROSE_GOLD, a));
    }
    DrawRectangle(le, Config::HIT_Y - 1, re - le, 2, ColorAlpha(Config::ROSE_GOLD, 0.8f + beatPulse * 0.2f));
    DrawCircleV({le - 4, Config::HIT_Y}, 5, ColorAlpha(Config::ROSE_GOLD, 0.7f));
    DrawCircleV({re + 4, Config::HIT_Y}, 5, ColorAlpha(Config::ROSE_GOLD, 0.7f));
    for (int i = 0; i < Config::LANES; i++) {
        float cx = Config::FIELD_X + (i + 0.5f) * Config::LANE_W;
        DrawCircleV({cx, Config::HIT_Y}, 3, ColorAlpha(Config::PASTEL[i], 0.3f + laneFlash[i] * 0.4f));
    }
}

void Renderer::drawReceptors(const float laneFlash[], const bool keysDown[]) {
    for (int i = 0; i < Config::LANES; i++) {
        float cx = Config::FIELD_X + (i + 0.5f) * Config::LANE_W;
        float cy = Config::HIT_Y + 36;
        if (laneFlash[i] > 0.1f) {
            for (int g = 3; g >= 0; g--)
                DrawCircleV({cx, Config::HIT_Y}, (18 + g * 14) * laneFlash[i],
                            ColorAlpha(Config::PASTEL[i], laneFlash[i] * 0.12f * (4 - g)));
            DrawCircleV({cx, Config::HIT_Y}, 10 * laneFlash[i], ColorAlpha(WHITE, laneFlash[i] * 0.4f));
        }
        if (laneFlash[i] > 0)
            DrawCircleV({cx, cy}, 20, ColorAlpha(Config::PASTEL[i], laneFlash[i] * 0.2f));
        DrawCircleV({cx, cy}, 18, ColorAlpha(Config::PASTEL_LIGHT[i], 0.6f + laneFlash[i] * 0.3f));
        DrawCircleLines((int)cx, (int)cy, 18, ColorAlpha(Config::ROSE_GOLD, 0.35f + laneFlash[i] * 0.3f));
        DrawText(Config::KEY_LABEL[i], (int)(cx - 5), (int)(cy - 6), 15,
                 keysDown[i] ? Config::ROSE_GOLD : ColorAlpha(Config::INK_LIGHT, 0.4f));
    }
}

void Renderer::drawParticles(const std::vector<Particle>& particles) {
    for (auto& p : particles) {
        float a = p.life / p.maxLife;
        if (p.sparkle) {
            drawSparkle(p.pos, p.size * a * 1.5f, ColorAlpha(p.color, a * 0.85f));
        } else {
            DrawCircleV(p.pos, p.size * a * 2.2f, ColorAlpha(p.color, a * 0.12f));
            DrawCircleV(p.pos, p.size * a, ColorAlpha(p.color, a * 0.8f));
        }
    }
}

void Renderer::drawScreenFlash(float flash) {
    if (flash > 0.01f)
        DrawRectangle(0, 0, Config::SW, Config::SH, ColorAlpha(WHITE, flash * 0.08f));
}

void Renderer::drawJudgment(JudgeResult judge, float elapsed) {
    if (judge == JudgeResult::NONE || elapsed > 0.6f) return;
    float a = 1 - elapsed / 0.6f;
    float sc = elapsed < 0.07f ? 1 + (0.07f - elapsed) * 8 : 1;
    const char* txt = "";
    Color jc = WHITE;
    if (judge == JudgeResult::PERFECT)      { txt = "PERFECT"; jc = {255, 150, 180, 255}; }
    else if (judge == JudgeResult::GREAT)    { txt = "GREAT";   jc = {130, 200, 255, 255}; }
    else if (judge == JudgeResult::GOOD)     { txt = "GOOD";    jc = {180, 220, 160, 255}; }
    else if (judge == JudgeResult::MISS)     { txt = "MISS";    jc = {220, 160, 160, 255}; }
    int fs = (int)(28 * sc);
    int tw = MeasureText(txt, fs);
    DrawText(txt, Config::SW / 2 - tw / 2 + 1, (int)(Config::HIT_Y - 80 - elapsed * 40) + 1, fs,
             ColorAlpha(Config::ROSE_GOLD, a * 0.2f));
    DrawText(txt, Config::SW / 2 - tw / 2, (int)(Config::HIT_Y - 80 - elapsed * 40), fs, ColorAlpha(jc, a));
}

void Renderer::drawUI(int score, int combo, float comboScale, float progress) {
    DrawText(TextFormat("SCORE  %08d", score), 15, 12, 20, Config::INK);
    if (combo > 2) {
        int fs = (int)(30 * comboScale);
        const char* ct = TextFormat("%d", combo);
        int tw = MeasureText(ct, fs);
        int cx = Config::SW / 2 - tw / 2, cy = (int)(Config::HIT_Y - 140);
        Color cc = combo > 50 ? (Color){255, 160, 185, 255}
                  : combo > 20 ? (Color){225, 160, 135, 255} : (Color){160, 140, 150, 255};
        DrawText(ct, cx - 1, cy - 1, fs, ColorAlpha(cc, 0.15f * comboScale));
        DrawText(ct, cx, cy, fs, cc);
        int cw = MeasureText("COMBO", 11);
        DrawText("COMBO", Config::SW / 2 - cw / 2, cy + fs + 2, 11, ColorAlpha(Config::ROSE_GOLD, 0.45f));
    }
    DrawRectangle(0, Config::SH - 3, (int)(Config::SW * progress), 3, ColorAlpha(Config::ROSE_GOLD, 0.5f));
}

void Renderer::drawCountdown(int count) {
    if (count <= 0) return;
    const char* txt;
    if (count >= 4)      txt = "READY";
    else if (count == 3) txt = "3";
    else if (count == 2) txt = "2";
    else                 txt = "1";

    float frac = fmodf(GetTime(), 1.0f);
    float scale = 1.0f + (1.0f - frac) * 0.3f;
    float alpha = 0.6f + (1.0f - frac) * 0.4f;
    int fs = (int)(80 * scale);
    int tw = MeasureText(txt, fs);
    int cx = Config::SW / 2 - tw / 2;
    int cy = Config::SH / 2 - fs / 2 - 40;

    DrawCircleV({(float)Config::SW / 2, (float)Config::SH / 2 - 40}, 100,
                ColorAlpha(Config::PASTEL[0], 0.08f));
    DrawText(txt, cx + 2, cy + 2, fs, ColorAlpha(Config::INK, 0.1f));
    DrawText(txt, cx, cy, fs, ColorAlpha(Config::ROSE_GOLD, alpha));
}

void Renderer::drawDemoOverlay(const std::string& title, float bgPhase) {
    // DEMO badge top-right
    float a = 0.6f + sinf(bgPhase * 6) * 0.3f;
    DrawRectangle(Config::SW - 140, 8, 132, 30, ColorAlpha(Config::PASTEL[0], 0.2f));
    DrawText("AUTO DEMO", Config::SW - 135, 13, 18, ColorAlpha(Config::PASTEL[0], a));

    // Song title bar at bottom
    int tw = MeasureText(title.c_str(), 20);
    DrawRectangle(Config::SW / 2 - tw / 2 - 15, Config::SH - 65, tw + 30, 28,
                  ColorAlpha(Config::INK, 0.15f));
    DrawText(title.c_str(), Config::SW / 2 - tw / 2, Config::SH - 62, 20,
             ColorAlpha(Config::ROSE_GOLD, 0.7f));

    // ESC hint
    DrawText("ESC to stop", Config::SW / 2 - 45, Config::SH - 35, 14,
             ColorAlpha(Config::INK_LIGHT, 0.3f));
}

void Renderer::drawMenu(float bgPhase) {
    ClearBackground(Config::BG_CREAM);
    for (auto& p : petals_) {
        float a = 0.2f + sinf(bgPhase * 2 + p.phase) * 0.15f;
        DrawCircleV({p.x, p.y}, p.size, ColorAlpha(p.tint, a));
    }
    for (int ring = 0; ring < 2; ring++) {
        float br = 100 + ring * 50;
        int n = 6 + ring * 3;
        for (int i = 0; i < n; i++) {
            float ang = bgPhase * (0.15f + ring * 0.08f) + (float)i / n * PI * 2;
            float r = br + sinf(bgPhase * 1.2f + i + ring) * 12;
            DrawCircleLines((int)(Config::SW / 2 + cosf(ang) * r),
                            (int)(Config::SH * 0.4f + sinf(ang) * r * 0.35f),
                            12 + ring * 6, ColorAlpha(Config::PASTEL[(i + ring) % 6], 0.12f));
        }
    }
    DrawText("aeacrA", Config::SW / 2 - 85, 140, 50, Config::PASTEL[0]);
    DrawText("aeacrA", Config::SW / 2 - 83, 138, 50, ColorAlpha(WHITE, 0.4f));
    DrawLineBezier({Config::SW / 2 - 200, 200}, {Config::SW / 2 + 200, 200}, 1, ColorAlpha(Config::ROSE_GOLD, 0.3f));
