try:
    from tqdm import tqdm  # type: ignore
except Exception:
    class tqdm:
        def __init__(self, iterable=None, total=None, desc=None, leave=False, **kwargs):
            self.iterable = iterable
            self.total = total
            self._count = 0

        def __iter__(self):
            if self.iterable is None:
                return iter([])
            return iter(self.iterable)

        def update(self, n=1):
            self._count += n

        def set_postfix(self, *args, **kwargs):
            pass

        def close(self):
            pass


def _read_jsonl_rows(path: str) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    if not path or (not os.path.exists(path)):
        return rows
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(json.loads(line))
            except Exception:
                pass
    return rows


class ExperimentRunner:
    def __init__(
        self,
        client,
        model: str,
        temperature: float,
        logs_dir: str,
        ci95_enable: bool,
        ci95_threshold: float,
        max_trials_per_word: int,
        rating_dimension: str = "concreteness",
        emotion_type: str = "joy",
    ):
        self.client = client
        self.model = model
        self.temperature = temperature
        self.logs_dir = logs_dir
        self.ci95_enable = ci95_enable
        self.ci95_threshold = ci95_threshold
        self.max_trials_per_word = max_trials_per_word
        self.rating_dimension = rating_dimension
        self.emotion_type = emotion_type

    @staticmethod
    def _parse_rating_int_1_100(text: Optional[str]) -> Optional[int]:
        if not text:
            return None
        m = re.search(r"(?<!\d)(100|[1-9]\d?)(?!\d)", str(text))
        if not m:
            return None
        try:
            val = int(m.group(1))
        except ValueError:
            return None
        if 1 <= val <= 100:
            return val
        return None

    def _one_isolated_rating(self, word: str, dimension: Optional[str] = None) -> Dict[str, Any]:
        asked_dim = dimension or self.rating_dimension
        messages = [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": build_user_prompt(word, asked_dim, emotion_type=self.emotion_type)},
        ]
        content = self.client.chat_completion(self.model, messages, self.temperature)
        rating = self._parse_rating_int_1_100(content)
        row = {
            "word": word,
            "response_text": content,
            "rating": rating,
            "asked_dimension": asked_dim,
        }
        if asked_dim == "emotion":
            row["asked_emotion_type"] = self.emotion_type
        return row

    @staticmethod
    def _validate_dimensions(words: List[str], dimensions: Optional[List[str]]) -> None:
        if dimensions is None:
            return
        if len(dimensions) != len(words):
            raise ValueError(
                f"dimensions length mismatch: len(words)={len(words)} but len(dimensions)={len(dimensions)}"
            )

    def run_experiment1_isolated(self, words: List[str], dimensions: Optional[List[str]] = None) -> Dict[str, Any]:
        self._validate_dimensions(words, dimensions)

        raw_rows: List[Dict[str, Any]] = []
        summary_rows: List[Dict[str, Any]] = []

        disable_bar = not sys.stderr.isatty()
        outer = tqdm(total=len(words), desc="Experiment 1 (isolated)", leave=True, disable=disable_bar)

        for i, w in enumerate(words):
            asked_dim = dimensions[i] if dimensions is not None else self.rating_dimension

            ratings: List[float] = []
            attempts = 0
            hw_display: Optional[float] = None

            while True:
                attempts += 1
                row = self._one_isolated_rating(w, asked_dim)
                raw_row = {
                    "word": w,
                    "rating": row["rating"],
                    "text": row["response_text"],
                    "asked_dimension": asked_dim,
                }
                if asked_dim == "emotion":
                    raw_row["asked_emotion_type"] = self.emotion_type
                raw_rows.append(raw_row)
                if row["rating"] is not None:
                    ratings.append(float(row["rating"]))

                if len(ratings) >= 2:
                    hw_display = ci95_half_width(ratings)
                    outer.set_postfix({"word": w, "dim": asked_dim, "n": len(ratings), "CI95": f"{hw_display:.3f}"})
                else:
                    outer.set_postfix({"word": w, "dim": asked_dim, "n": len(ratings)})

                if not self.ci95_enable:
                    break
                if len(ratings) >= 2:
                    hw = hw_display if hw_display is not None else ci95_half_width(ratings)
                    if hw <= self.ci95_threshold:
                        break
                if attempts >= self.max_trials_per_word:
                    break

            summ = summary(ratings) if ratings else {"mean": None, "std": None, "n": 0, "ci95_half_width": None}
            summary_row = {"word": w, "asked_dimension": asked_dim, **summ}
            if asked_dim == "emotion":
                summary_row["asked_emotion_type"] = self.emotion_type
            summary_rows.append(summary_row)
            outer.update(1)

        outer.close()
        return {"raw": raw_rows, "summary": summary_rows}

    def run_experiment2_sequential(
        self,
        words: List[str],
        dimensions: Optional[List[str]] = None,
        out_jsonl_path: Optional[str] = None,
        out_csv_path: Optional[str] = None,
        resume: bool = False,
        context_window: Optional[int] = None,
        compact_prompt: bool = False,
    ) -> Dict[str, Any]:
        self._validate_dimensions(words, dimensions)

        def _user_prompt(word: str, dim: str) -> str:
            if compact_prompt:
                if dim == "emotion":
                    return f"emotion:{self.emotion_type}: {word}"
                return f"{dim}: {word}"
            return build_user_prompt(word, dim, emotion_type=self.emotion_type)

        raw_rows: List[Dict[str, Any]] = []
        start_i = 0

        if resume and out_jsonl_path and os.path.exists(out_jsonl_path):
            raw_rows = _read_jsonl_rows(out_jsonl_path)
            start_i = len(raw_rows)
            if start_i > len(words):
                raw_rows = raw_rows[: len(words)]
                start_i = len(raw_rows)

        messages: List[Dict[str, str]] = [{"role": "system", "content": SYSTEM_PROMPT}]

        if start_i > 0:
            ctx_rows = raw_rows
            if context_window is not None:
                k0 = int(context_window)
                if k0 < 0:
                    raise ValueError("context_window must be >= 0 or None")
                ctx_rows = raw_rows[-k0:] if k0 > 0 else []

            for r in ctx_rows:
                w0 = str(r.get("word"))
                dim0 = str(r.get("asked_dimension") or self.rating_dimension)
                messages.append({"role": "user", "content": _user_prompt(w0, dim0)})
                messages.append({"role": "assistant", "content": str(r.get("text") or "")})

        disable_bar = not sys.stderr.isatty()
        try:
            bar = tqdm(total=len(words), desc="Experiment 2 (sequential)", leave=True, disable=disable_bar, initial=start_i)
        except TypeError:
            bar = tqdm(total=len(words), desc="Experiment 2 (sequential)", leave=True, disable=disable_bar)
            if start_i:
                bar.update(start_i)

        for i in range(start_i, len(words)):
            w = words[i]
            asked_dim = dimensions[i] if dimensions is not None else self.rating_dimension

            user = {"role": "user", "content": _user_prompt(w, asked_dim)}
            messages.append(user)

            if context_window is not None:
                k = int(context_window)
                if k < 0:
                    raise ValueError("context_window must be >= 0 or None")
                keep = 2 * k + 1
                if len(messages) > 1 + keep:
                    messages = [messages[0]] + messages[-keep:]

            content = self.client.chat_completion(self.model, messages, self.temperature)
            rating = self._parse_rating_int_1_100(content)

            row = {"word": w, "rating": rating, "text": content, "asked_dimension": asked_dim}
            if asked_dim == "emotion":
                row["asked_emotion_type"] = self.emotion_type
            raw_rows.append(row)

            if out_jsonl_path:
                append_jsonl(out_jsonl_path, row)
            if out_csv_path:
                fieldnames = ["word", "rating", "text", "asked_dimension"]
                if asked_dim == "emotion":
                    fieldnames.append("asked_emotion_type")
                append_csv_dict(out_csv_path, row, fieldnames)

            messages.append({"role": "assistant", "content": content})

            bar.set_postfix({"word": w, "dim": asked_dim})
            bar.update(1)
            time.sleep(0.05)

        bar.close()
        return {"raw": raw_rows}

    def run_none_autoregressive(self, n_trials: int) -> Dict[str, Any]:
        if n_trials < 1:
            raise ValueError("n_trials must be >= 1")

        raw_rows: List[Dict[str, Any]] = []
        messages = [{"role": "system", "content": SYSTEM_PROMPT}]

        disable_bar = not sys.stderr.isatty()
        bar = tqdm(total=n_trials, desc="Experiment NONE (autoregressive)", leave=True, disable=disable_bar)

        prev_rating: Optional[int] = None
        for t in range(1, n_trials + 1):
            messages.append({"role": "user", "content": build_none_prompt(t)})

            content = self.client.chat_completion(self.model, messages, self.temperature)
            rating = self._parse_rating_int_1_100(content)

            raw_rows.append({"trial": t, "rating": rating, "prev_rating": prev_rating, "text": content})
            messages.append({"role": "assistant", "content": content})

            if rating is not None:
                prev_rating = rating

            bar.set_postfix({"trial": t, "rating": rating})
            bar.update(1)
            time.sleep(0.05)

        bar.close()
        return {"raw": raw_rows}

/* =====================================================================
 * 清华 OJ 题目批量保存为 Markdown  (v2 - iframe 渲染版)
 *
 * 原理：TriUOJ 是 SPA，题目正文由 JS 动态加载，fetch 只能拿到空壳。
 *      本脚本用隐藏 iframe 加载每道题，等 JS 渲染完成后读取真实 DOM。
 *
 * 使用方法：
 *   1. Chrome / Edge 登录 OJ，打开任一题目页
 *      (如 https://oj.cs.tsinghua.edu.cn/course/90/contest/1038/problem/0)
 *   2. F12 → Console
 *   3. 粘贴本脚本回车
 *   4. 弹窗选择 OOP/HW 文件夹（或新建）
 *   5. 等待 5 道题完成
 * ===================================================================== */
(async () => {
  'use strict';

  const m = location.href.match(/course\/(\d+)\/contest\/(\d+)/);
  if (!m) {
    console.error('❌ 请在 OJ contest 页面运行（URL 含 course/xx/contest/yy）');
    return;
  }
  const [, course, contest] = m;
  const base = `https://oj.cs.tsinghua.edu.cn/course/${course}/contest/${contest}`;
  console.log(`🔍 course=${course}, contest=${contest}`);

  // ---------- 加载 Turndown ----------
  if (!window.TurndownService) {
    console.log('⏳ 加载 Turndown…');
    await new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = 'https://cdn.jsdelivr.net/npm/turndown@7.1.2/dist/turndown.js';
      s.onload = resolve;
      s.onerror = () => {
        s.src = 'https://unpkg.com/turndown@7.1.2/dist/turndown.js';
        s.onload = resolve;
        s.onerror = () => reject(new Error('Turndown 加载失败'));
      };
      document.head.appendChild(s);
    });
  }
  const td = new TurndownService({
    headingStyle: 'atx', codeBlockStyle: 'fenced',
    bulletListMarker: '-', emDelimiter: '_',
  });
  td.addRule('keepPre', {
    filter: ['pre'],
    replacement: (_, node) => '\n\n```\n' + node.textContent + '\n```\n\n',
  });
  // 去掉页脚等噪声
  td.remove(['script', 'style', 'nav', 'footer', 'header', 'noscript']);

  // ---------- 选文件夹 ----------
  let dir = null;
  if (window.showDirectoryPicker) {
    try {
      dir = await window.showDirectoryPicker({ mode: 'readwrite' });
      console.log(`📂 文件夹: ${dir.name}`);
    } catch (e) {
      console.warn('⚠️ 未选文件夹，改用普通下载');
    }
  }
  // 写入：文件夹 dir/<folderName>/<fileName>，无文件夹API时退化为 <folderName>_<fileName>
  async function saveFile(folderName, fileName, content) {
    if (dir) {
      const sub = await dir.getDirectoryHandle(folderName, { create: true });
      const fh = await sub.getFileHandle(fileName, { create: true });
      const w = await fh.createWritable();
      await w.write(content); await w.close();
    } else {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(new Blob([content], { type: 'text/markdown;charset=utf-8' }));
      a.download = `${folderName}/${fileName}`.replace('/', '_'); // 普通下载无法建子目录，用前缀
      a.click();
      setTimeout(() => URL.revokeObjectURL(a.href), 1000);
    }
  }

  // ---------- iframe 渲染题目 ----------
  function loadIframe(url) {
    return new Promise((resolve, reject) => {
      const iframe = document.createElement('iframe');
      iframe.style.cssText = 'position:fixed;right:0;bottom:0;width:500px;height:400px;border:1px solid #0a0;z-index:99999;opacity:.6;';
      iframe.src = url;
      iframe.onload = () => resolve(iframe);
      iframe.onerror = () => reject(new Error('iframe 加载失败（可能被 X-Frame-Options 拦截）'));
      document.body.appendChild(iframe);
      setTimeout(() => reject(new Error('iframe 加载超时')), 15000);
    });
  }

  // 等待正文出现（轮询 DOM 直到内容稳定）
  async function waitForContent(getBody, { minLen = 300, stableMs = 1200, timeout = 12000 } = {}) {
    const start = Date.now();
    let lastLen = -1, stableSince = start;
    while (Date.now() - start < timeout) {
      await new Promise(r => setTimeout(r, 300));
      const len = getBody().innerHTML.length;
      if (len >= minLen) {
        if (len === lastLen) {
          if (Date.now() - stableSince >= stableMs) return true;
        } else {
          stableSince = Date.now();
        }
      }
      lastLen = len;
    }
    return false;
  }

  // 正文选择器（按优先级）
  function extractContent(doc) {
    const sels = [
      '.problem-content', '.problem-body', '.problem-statement',
      '.markdown-body', '.problem-detail', '.problem',
      '[class*="problem"][class*="content"]',
      'article', 'main', '.content', '#app',
    ];
    for (const sel of sels) {
      const el = doc.querySelector(sel);
      if (el && el.innerText.trim().length > 100) {
        // 去掉明显是导航/页脚的子节点
        el.querySelectorAll('nav,footer,header,.navbar,.footer,.sidebar,nav,script,style').forEach(n => n.remove());
        return { el, via: sel };
      }
    }
    return { el: doc.body, via: 'body(兜底)' };
  }

  function extractTitle(doc, idx) {
    const t = doc.querySelector('h1,h2,.title,.problem-title,[class*="title"]')?.textContent;
    return (t || `Problem ${idx}`).trim().replace(/\s+/g, ' ').slice(0, 120);
  }

  // ---------- 主循环 ----------
  const N = 5;
  for (let i = 0; i < N; i++) {
    const url = `${base}/problem/${i}`;
    console.log(`\n➡️ [${i + 1}/${N}] ${url}`);
    let iframe;
    try {
      iframe = await loadIframe(url);
      const idoc = iframe.contentDocument;
      await waitForContent(() => idoc.body);
      // 再额外等一会儿确保 Markdown 渲染完成
      await new Promise(r => setTimeout(r, 1500));

      const { el, via } = extractContent(idoc);
      const title = extractTitle(idoc, i);
      const preview = el.innerText.replace(/\s+/g, ' ').slice(0, 80);
      console.log(`   📝 ${title}\n   选择器: ${via} | 预览: ${preview}…`);

      const bodyMd = td.turndown(el.innerHTML);
      const md =
        `# ${title}\n\n` +
        `> 来源: <${url}>\n` +
        `> course ${course} · contest ${contest} · problem ${i}\n\n---\n\n` +
        `${bodyMd.trim()}\n`;
      await saveFile(`Problem_${i}.md`, md);
      console.log(`   ✅ 已保存 Problem_${i}.md`);
    } catch (e) {
      console.error(`   ❌ 第 ${i} 题失败: ${e.message}`);
      console.error('   若是 X-Frame-Options 拦截，请告诉我，我改用 API 方案');
    } finally {
      if (iframe) iframe.remove();
    }
    await new Promise(r => setTimeout(r, 800));
  }
  console.log('\n🎉 完成！');
})();

#include <iostream>
#include <string>
#include <regex>

using namespace std;

// 自动复制到剪贴板
void copyToClipboard(const string& text) {
#ifdef _WIN32
    string cmd = "echo " + text + " | clip";
    system(cmd.c_str());
#elif __APPLE__
    FILE* pipe = popen("pbcopy", "w");
    if (pipe) {
        fputs(text.c_str(), pipe);
        pclose(pipe);
    }
#else
    string cmd = "echo -n \"" + text + "\" | xclip -selection clipboard";
    system(cmd.c_str());
#endif
}

int main() {
    string input;
    // 匹配变量，排除数学函数
    regex var_regex("\\b(?!sqrt|sin|cos|tan|log|ln|exp|abs|pow|pi|calc|round)[a-zA-Z_][a-zA-Z0-9_]*\\b");

    while (true) {
        cout << "请输入：";
        if (!getline(cin, input) || input == "exit") break;
        if (input.empty()) continue;

        // 核心转换逻辑
        string fmt = regex_replace(input, var_regex, "\"+str($&)+\"");
        string final_str = "\"" + fmt + "\"";

        // 清理冗余引号拼接
        final_str = regex_replace(final_str, regex("\"\"\\+"), "");
        final_str = regex_replace(final_str, regex("\\+\"\""), "");

        // 组装最终字符串
        string result = "cal(" + final_str + ", result: 1)";

        copyToClipboard(result);

        cout << "typst：" << result << " (已存入剪贴板)" << endl;
        cout << "下一个：" << endl;
    }
    return 0;
}
